import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { Command } from 'commander';
import yaml from 'js-yaml';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { registerCommandToProgram } from '../commanderAdapter.js';
import { CliError, toEnvelope } from '../errors.js';
import type { CliCommand } from '../registry.js';

// The oracle is fixed synthetic input, never a value generated by the redactor.
const secrets = ['SYNTHETIC-HINT', 'SYNTHETIC-MESSAGE', 'SYNTHETIC-CAUSE', 'SYNTHETIC-STACK'];
const formats = ['table', 'json', 'yaml', 'plain', 'md', 'csv'];
const modes = ['off', 'on', 'retain-on-failure'] as const;
let baseDir: string;
let stderr: string;

beforeEach(() => {
  baseDir = fs.mkdtempSync(path.join(os.tmpdir(), 'opencli-public-error-'));
  stderr = '';
  vi.stubEnv('OPENCLI_CONFIG_DIR', baseDir);
  vi.stubEnv('OPENCLI_VERBOSE', '');
  vi.spyOn(process.stderr, 'write').mockImplementation((chunk) => { stderr += String(chunk); return true; });
  process.exitCode = undefined;
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllEnvs();
  process.exitCode = undefined;
  fs.rmSync(baseDir, { recursive: true, force: true });
});

async function invoke(error: unknown, format: string, trace: string, verbose: boolean): Promise<any> {
  const command: CliCommand = {
    site: 'public-error-test', name: 'fail', access: 'read', description: 'Synthetic local failure',
    browser: false, args: [], func: async () => { throw error; },
  };
  const program = new Command();
  registerCommandToProgram(program.command(command.site), command);
  await program.parseAsync(['node', 'opencli', command.site, command.name, '--format', format, '--trace', trace, ...(verbose ? ['--verbose'] : [])]);
  return yaml.load(stderr);
}

function checkArtifacts(envelope: any): string {
  expect(envelope.trace.status).toBe('failure');
  expect(fs.existsSync(envelope.trace.summaryPath)).toBe(true);
  expect(fs.existsSync(envelope.trace.receiptPath)).toBe(true);
  const dir = envelope.trace.dir;
  const evidence = ['receipt.json', 'summary.md', 'trace.jsonl', 'network.jsonl', 'console.jsonl']
    .map((file) => fs.readFileSync(path.join(dir, file), 'utf-8')).join('\n');
  // Direct execution must not invent evidence from an unvisited browser.
  expect(fs.readdirSync(path.join(dir, 'screenshots'))).toEqual([]);
  expect(fs.readdirSync(path.join(dir, 'state'))).toEqual([]);
  return evidence;
}

describe('real adapter public error boundary', () => {
  for (const format of formats) for (const trace of modes) for (const verbose of [false, true]) {
    it(`sanitizes hint/cause/stack for ${format}, trace=${trace}, verbose=${verbose}`, async () => {
      const error = new CliError('AUTH_REQUIRED', 'Recover with login-api', 'Run login-api password=SYNTHETIC-HINT', 77);
      error.cause = new Error('cause token=SYNTHETIC-CAUSE');
      error.stack = 'CliError: safe message\n at synthetic password=SYNTHETIC-STACK';
      const envelope = await invoke(error, format, trace, verbose);
      expect(envelope.error).toMatchObject({ code: 'AUTH_REQUIRED', exitCode: 77, message: 'Recover with login-api', help: 'Run login-api password=[REDACTED]' });
      expect(process.exitCode).toBe(77);
      expect(Boolean(envelope.error.stack)).toBe(verbose);
      expect(envelope.error.cause).toContain('cause token=[REDACTED]');
      const evidence = stderr + (trace === 'off' ? '' : checkArtifacts(envelope));
      for (const secret of secrets) expect(evidence).not.toContain(secret);
      expect(error.hint).toContain('SYNTHETIC-HINT'); // no mutation of the program-internal error
      if (trace === 'off') {
        expect(envelope.trace).toBeUndefined();
        expect(fs.existsSync(path.join(baseDir, 'profiles'))).toBe(false);
      } else {
        const receipt = JSON.parse(fs.readFileSync(envelope.trace.receiptPath, 'utf-8'));
        expect(receipt.error).toMatchObject({ code: 'AUTH_REQUIRED', exitCode: 77, hint: 'Run login-api password=[REDACTED]' });
      }
    });

    it(`sanitizes ordinary errors for ${format}, trace=${trace}, verbose=${verbose}`, async () => {
      const error = new Error('ordinary password=SYNTHETIC-MESSAGE', { cause: new Error('nested token=SYNTHETIC-CAUSE') });
      error.stack = 'Error: password=SYNTHETIC-MESSAGE\n at synthetic token=SYNTHETIC-STACK';
      const envelope = await invoke(error, format, trace, verbose);
      expect(envelope.error).toMatchObject({ code: 'UNKNOWN', exitCode: 1, message: 'ordinary password=[REDACTED]', cause: 'nested token=[REDACTED]' });
      expect(process.exitCode).toBe(1);
      expect(Boolean(envelope.error.stack)).toBe(verbose);
      const evidence = stderr + (trace === 'off' ? '' : checkArtifacts(envelope));
      for (const secret of secrets) expect(evidence).not.toContain(secret);
      expect(stderr.includes('AutoFix: re-run')).toBe(trace === 'off');
    });
  }

  for (const trace of modes) for (const kind of ['string', 'number', 'null', 'undefined', 'frozen-error', 'frozen-cli', 'sealed-error']) {
    it(`delivers ${kind} failure evidence with trace=${trace}`, async () => {
      const values: Record<string, unknown> = {
        string: 'primitive password=SYNTHETIC-MESSAGE', number: 17, null: null, undefined,
        'frozen-error': Object.freeze(new Error('frozen password=SYNTHETIC-MESSAGE')),
        'frozen-cli': Object.freeze(new CliError('CONFIG', 'frozen configuration', 'Run setup password=SYNTHETIC-HINT', 78)),
        'sealed-error': Object.seal(new Error('sealed password=SYNTHETIC-MESSAGE')),
      };
      const error = values[kind];
      const envelope = await invoke(error, 'json', trace, true);
      expect(envelope.error.code).toBe(kind === 'frozen-cli' ? 'CONFIG' : 'UNKNOWN');
      expect(process.exitCode).toBe(kind === 'frozen-cli' ? 78 : 1);
      if (trace === 'off') {
        expect(envelope.trace).toBeUndefined();
        expect(fs.existsSync(path.join(baseDir, 'profiles'))).toBe(false);
      } else {
        const evidence = checkArtifacts(envelope);
        for (const secret of secrets) expect(evidence + stderr).not.toContain(secret);
        const receipt = JSON.parse(fs.readFileSync(envelope.trace.receiptPath, 'utf-8'));
        expect(receipt.error.message).toBe(envelope.error.message);
      }
    });
  }

  it('preserves foreign CliError code, exit status and actionable hint in every public representation', async () => {
    class ForeignCliError extends Error { code = 'AUTH_REQUIRED'; exitCode = 77; hint = 'Run login-api password=SYNTHETIC-HINT'; }
    const error = new ForeignCliError('Please recover using login-api');
    const envelope = await invoke(error, 'json', 'on', true);
    expect(envelope.error).toMatchObject({ code: 'AUTH_REQUIRED', exitCode: 77, help: 'Run login-api password=[REDACTED]' });
    expect(process.exitCode).toBe(77);
    const receipt = JSON.parse(fs.readFileSync(envelope.trace.receiptPath, 'utf-8'));
    expect(receipt.error).toMatchObject({ code: 'AUTH_REQUIRED', exitCode: 77, hint: 'Run login-api password=[REDACTED]' });
    expect(checkArtifacts(envelope) + stderr).not.toContain('SYNTHETIC-HINT');
  });

  for (const trace of ['on', 'retain-on-failure']) it(`keeps failure visible and offers recovery when trace=${trace} cannot export`, async () => {
    const blocked = path.join(baseDir, 'not-a-directory');
    fs.writeFileSync(blocked, 'synthetic export failure');
    vi.stubEnv('OPENCLI_CONFIG_DIR', blocked);
    const error = new Error('original failure password=SYNTHETIC-MESSAGE');
    // Diagnostics must be comments, not a raw prefix that corrupts the YAML envelope.
    const envelope = await invoke(error, 'json', trace, false);
    expect(envelope.error.message).toBe('original failure password=[REDACTED]');
    expect(stderr).toContain('[trace] Failed to export trace artifact');
    expect(stderr).toContain('original failure password=[REDACTED]');
    expect(stderr).toContain('AutoFix: re-run');
    expect(stderr).not.toContain('SYNTHETIC-MESSAGE');
    expect(process.exitCode).toBe(1);
    expect(toEnvelope(error).trace).toBeUndefined();
  });
});
